begin;

alter table public.db_categories add column if not exists restricted boolean not null default false;
create table if not exists public.db_category_access_grants (user_id uuid not null references public.staff_users(id) on delete cascade, category_id uuid not null references public.db_categories(id) on delete cascade, level text not null check (level in ('view','contribute','approve')), granted_by uuid references public.staff_users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(user_id,category_id));
alter table public.db_category_access_grants enable row level security;
revoke all on table public.db_category_access_grants from public,anon,authenticated; grant select,insert,update,delete on table public.db_category_access_grants to service_role;
create or replace function public.db_restricted_category_id(p_category_id uuid) returns uuid language sql stable security definer set search_path to 'public','pg_temp' as $function$ select case when child.restricted then child.id when parent.restricted then parent.id else null end from public.db_categories child left join public.db_categories parent on parent.id=child.parent_id where child.id=p_category_id $function$;
create or replace function public.db_category_is_restricted(p_category_id uuid) returns boolean language sql stable security definer set search_path to 'public','pg_temp' as $function$ select public.db_restricted_category_id(p_category_id) is not null $function$;
revoke all on function public.db_restricted_category_id(uuid) from public,anon,authenticated; grant execute on function public.db_restricted_category_id(uuid) to service_role; revoke all on function public.db_category_is_restricted(uuid) from public,anon,authenticated; grant execute on function public.db_category_is_restricted(uuid) to service_role;
